 static void strictResponse(Map<String,Object>data)throws Exception {
  byte[]bytes=org.securemail.community.http.StrictJson.bytes(Map.of("ok",true,"data",data,"authorizationEpoch",1,"serverTime",1_800_000_000_000L,"requestIdentity","a".repeat(64),"requestSha256","b".repeat(64)));
  assertTrue(bytes.length<8*1024*1024);assertEquals(true,org.securemail.community.http.StrictJson.object(bytes,8*1024*1024).get("ok"));
 }
 @Test void graphKeepsCrossPageEdgesAndRechecksOtherEndpointAclAndFilters()throws Exception {
  Map<String,Object>a=published("library"),b=published("library"),hidden=draft("library");
  Map<String,Object>edge=call(alice,"library.link.propose",Map.of("from",a.get("id"),"to",b.get("id"),"explanation","На разных страницах"));call(alice,"library.link.decide",Map.of("id",edge.get("id"),"decision","APPROVE"));
  Map<String,Object>secret=call(alice,"library.link.propose",Map.of("from",hidden.get("id"),"to",b.get("id"),"explanation","Нельзя раскрывать"));call(alice,"library.link.decide",Map.of("id",secret.get("id"),"decision","APPROVE"));
  Set<String>nodes=new HashSet<>(),edges=new HashSet<>();String cursor="";int pages=0;
  do{Map<String,Object>page=call(bob,"library.graph",Map.of("cursor",cursor,"limit",1));strictResponse(page);for(Map<String,Object>node:items(Map.of("items",page.get("nodes"))))nodes.add((String)node.get("id"));for(Map<String,Object>e:items(Map.of("items",page.get("edges")))){assertTrue(nodes.contains(e.get("from"))&&nodes.contains(e.get("to")));assertTrue(edges.add((String)e.get("id")));}cursor=(String)page.get("nextCursor");assertTrue(++pages<=3);}while(!cursor.isEmpty());
  assertEquals(Set.of(a.get("id"),b.get("id")),nodes);assertEquals(Set.of(edge.get("id")),edges);
  assertTrue(((List<?>)call(bob,"library.graph",Map.of("query","неизвестный фильтр")).get("edges")).isEmpty());
 }
 @Test void denseGraphAndMaximumAclPagesFitStrictJsonWithoutLostNodesOrEdges()throws Exception {
  List<String>rights=new ArrayList<>(),users=new ArrayList<>(List.of(alice,bob)),orgs=new ArrayList<>();for(int n=0;n<32;n++)rights.add("CONTENT_TEST_"+n);for(int n=0;n<126;n++)users.add(String.format("%064x",n));for(int n=0;n<64;n++)orgs.add(UUID.randomUUID().toString());grant(alice,"GLOBAL",Set.copyOf(rights));grant(bob,"GLOBAL",Set.copyOf(rights));
  Map<String,Object>policy=Map.of("permissions",rights,"organizations",orgs,"users",users,"offlineAllowed",true);
  List<String>ids=new ArrayList<>();for(int n=0;n<64;n++){Map<String,Object>m=call(alice,"library.create",Map.of("title","я".repeat(297)+n,"body","🕊".repeat(280),"policy",policy));call(alice,"library.publish",Map.of("id",m.get("id"),"revision",1));ids.add((String)m.get("id"));}
  Collections.sort(ids);Set<String>expectedEdges=new HashSet<>();store.tx(db->{for(int x=0;x<ids.size();x++)for(int y=x+1;y<ids.size();y++){String edge=UUID.randomUUID().toString();sql(db,"INSERT INTO content_edge VALUES(?,?,?,?,?,?,?)",edge,ids.get(x),ids.get(y),"🕊".repeat(500),"APPROVED",alice,0);expectedEdges.add(edge);}return null;});
  Map<String,Object>listing=call(bob,"library.list",Map.of("limit",100));strictResponse(listing);assertEquals(64,items(listing).size());
  Set<String>seen=new HashSet<>(),gotEdges=new HashSet<>();String cursor="";int pages=0;boolean continuation=false;
  do{Map<String,Object>page=call(bob,"library.graph",Map.of("cursor",cursor,"limit",100));strictResponse(page);for(Map<String,Object>node:items(Map.of("items",page.get("nodes"))))seen.add((String)node.get("id"));for(Map<String,Object>edge:items(Map.of("items",page.get("edges")))){assertTrue(seen.contains(edge.get("from"))&&seen.contains(edge.get("to")));assertTrue(gotEdges.add((String)edge.get("id")),"No duplicate/lost edge across continuation");}String next=(String)page.get("nextCursor");assertNotEquals(cursor,next);cursor=next;continuation|=cursor.startsWith("E:");assertTrue(++pages<20);}while(!cursor.isEmpty());
  assertTrue(continuation);assertEquals(Set.copyOf(ids),seen);assertEquals(expectedEdges,gotEdges);
 }
